"""Render the generated parts of a dataset's ``DATA_CARD.md`` (ADR-0071).

    structbench-datagen card --dataset <dir> [--sweep <runs>/<name>]
        [--out FILE] [--check]

The card is the author's document with eight generated parts, each between a
pair of markers::

    <!-- card:variables:start (generated by structbench-datagen card; ...) -->
    ...
    <!-- card:variables:end -->

The stage replaces what is between each pair and leaves every other byte as
the author wrote it. It renders from records only: the definition, and, with
``--sweep``, the preflight stamp, the verification record, the convergence
record and each case's provenance and run record. Every part names the record
it was read from and that record's sha256, or says that the record does not
exist: an absent record is stated, never left blank, so a card for a
definition nothing has run for is a valid card.

The output is bytes with LF endings, no timestamp of its own, no absolute
path and no host name; rendering twice gives the same bytes. ``--check``
writes nothing and exits 1 when the file differs from its render. Exit codes:
0 written or unchanged, 1 ``--check`` found a difference, 2 refused (no
definition, a card without the markers).

The part renderers are pure functions of records, so they are tested without
a solver (plan of 2026-11-18).
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import statistics
import sys
from collections import Counter
from collections.abc import Callable, Mapping, Sequence
from dataclasses import dataclass, field, replace
from pathlib import Path
from typing import Any

from structbench.core.io import read_case
from structbench.datagen import generate
from structbench.datagen.definition import (
    Definition,
    DefinitionError,
    load_definition,
    load_problem,
    problem_sha256,
    siblings_sha256,
)
from structbench.verification import Verdict
from structbench.verification.criteria import DatasetReport, judge
from structbench.verification.report import from_json

CARD_FILE = "DATA_CARD.md"
#: The generated parts, in the order the template carries them.
PARTS = (
    "variables",
    "stored",
    "qoi",
    "survivors",
    "verification",
    "convergence",
    "resolution",
    "provenance",
)
_NOTE = "generated by structbench-datagen card; do not edit by hand"
_START = re.compile(r"<!-- card:([a-z_]+):start[^>]*-->")
#: The template before this stage: one comment per generated section.
_OLD_MARKER = re.compile(r"<!--\s*GENERATED\b")


class CardError(ValueError):
    """A card the stage cannot render into; says which part and why."""


def start_marker(part: str) -> str:
    return f"<!-- card:{part}:start ({_NOTE}) -->"


def end_marker(part: str) -> str:
    return f"<!-- card:{part}:end -->"


def _spans(text: str) -> dict[str, tuple[int, int]]:
    """Each part's (start of its body, end of its body) in ``text``."""
    if _OLD_MARKER.search(text):
        raise CardError(
            "the card is on the template of before 2026-11-18 (a single "
            "'<!-- GENERATED ... -->' comment per section); replace each with a "
            f"pair such as {start_marker('variables')} / {end_marker('variables')} "
            "around the lines that are generated (the parts: " + ", ".join(PARTS) + ")"
        )
    spans: dict[str, tuple[int, int]] = {}
    for match in _START.finditer(text):
        part = match.group(1)
        if part not in PARTS:
            raise CardError(f"card:{part}: not a part (one of {', '.join(PARTS)})")
        if part in spans:
            raise CardError(f"card:{part}: the start marker appears twice")
        close = text.find(end_marker(part), match.end())
        if close < 0:
            raise CardError(f"card:{part}: no end marker after its start")
        spans[part] = (match.end(), close)
    missing = [p for p in PARTS if p not in spans]
    if missing:
        raise CardError(
            f"card:{missing[0]}: no marker pair in the card "
            f"({start_marker(missing[0])} ... {end_marker(missing[0])})"
        )
    return spans


def render_card(text: str, parts: Mapping[str, str]) -> str:
    """``text`` with each part's body replaced; everything else untouched."""
    text = text.replace("\r\n", "\n")
    spans = _spans(text)
    out, at = [], 0
    for part, (begin, end) in sorted(spans.items(), key=lambda kv: kv[1]):
        body = parts[part].strip("\n")
        out += [text[at:begin], "\n", body, "\n" if body else ""]
        at = end
    return "".join(out) + text[at:]


#: The sections of a card, in order: (heading, generated part or None, what
#: the author writes there or None).
SECTIONS: tuple[tuple[str, str | None, str | None], ...] = (
    ("What it is", None, "what the dataset is and what it is for"),
    ("Model and why", None, "the model, and why this one"),
    ("Variables and splits", "variables", None),
    ("Stored data", "stored", None),
    (
        "Quantities of interest",
        "qoi",
        "what each quantity means and why it was chosen",
    ),
    ("Survivor log", "survivors", None),
    ("Verification of the runs", "verification", None),
    ("Discretization uncertainty", "convergence", None),
    (
        "Resolution and horizon",
        "resolution",
        "why each tolerance was chosen, and the scored horizon (the benchmark "
        "protocol's: it is declared in the benchmark definition, not here)",
    ),
    ("Validation against experiments", None, "what was compared, or that nothing was"),
    ("Known limitations", None, "what a user of the data must know"),
    ("Provenance and reproduction", "provenance", None),
)


def template_card(name: str) -> str:
    """An empty card for dataset ``name``: what ``new`` scaffolds."""
    out = [
        f"# {name} — data card",
        "",
        "<!-- The parts between `card:...:start` and `card:...:end` markers are",
        "rendered by `structbench-datagen card` and replaced on every render;",
        "everything else is the author's and is never touched. -->",
    ]
    for heading, part, author in SECTIONS:
        out += ["", f"## {heading}"]
        if part is not None:
            out += [start_marker(part), end_marker(part)]
        if author is not None:
            out.append(f"<!-- author: {author} -->")
    return "\n".join(out) + "\n"


def blank_card(text: str) -> str:
    """The card with every generated part emptied."""
    return render_card(text, dict.fromkeys(PARTS, ""))


# --- the records -----------------------------------------------------------------


def _sha256(path: Path) -> str:
    """The file's sha256 with LF endings, whatever a checkout wrote."""
    return hashlib.sha256(path.read_bytes().replace(b"\r\n", b"\n")).hexdigest()


def _source(name: str, sha: str | None) -> str:
    """The line that names the record a part was read from."""
    if sha is None:
        return f"*From `{name}`.*"
    return f"*From `{name}` (sha256 `{sha[:12]}…`).*"


def _load_json(path: Path) -> Any | None:
    if not path.is_file():
        return None
    return json.loads(path.read_text(encoding="utf-8"))


@dataclass(frozen=True)
class Records:
    """Everything the card reads; ``None`` and empty mean the record is absent.

    ``sweep`` says whether a sweep was read at all, so that "no sweep was
    given" and "the sweep holds no such record" stay two statements.
    """

    defn: Definition
    hashes: Mapping[str, str]
    planned: Mapping[str, int]
    rejected: Mapping[str, int]
    sweep: bool = False
    stamp: Mapping[str, Any] | None = None
    stamp_sha256: str | None = None
    report: DatasetReport | None = None
    measurements_sha256: str | None = None
    convergence: Mapping[str, Any] | None = None
    convergence_sha256: str | None = None
    convergence_source: str = "converge/convergence.json"
    provenance: Mapping[str, Mapping[str, Any]] = field(default_factory=dict)
    runs: Mapping[str, Mapping[str, Any]] = field(default_factory=dict)
    exported: frozenset[str] = frozenset()
    converted: frozenset[str] = frozenset()
    qoi_values: Mapping[str, Mapping[str, float]] = field(default_factory=dict)
    qoi_failures: Mapping[str, str] = field(default_factory=dict)


def _plan(
    defn: Definition, feasible: Callable[[dict[str, Any]], bool] | None
) -> tuple[dict[str, int], dict[str, int]]:
    """Cases planned per split, and the draws ``feasible()`` rejected per split.

    The rejections are in no record: the plan is recomputed with a counting
    hook, which the definition alone determines.
    """
    rejected: Counter[str] = Counter()
    current = {"split": ""}
    hook = None
    if feasible is not None:

        def hook(params: dict[str, Any]) -> bool:
            ok = bool(feasible(params))
            if not ok:
                rejected[current["split"]] += 1
            return ok

    planned: dict[str, int] = {}
    for split in defn.splits:
        current["split"] = split.name
        only = replace(defn, splits=(split,))
        planned[split.name] = len(generate.plan_cases(only, hook))
    return planned, {s.name: rejected[s.name] for s in defn.splits}


def load_records(dataset_dir: Path, sweep: Path | None) -> Records:
    """Read the definition and, when ``sweep`` is given, the sweep's records."""
    defn = load_definition(dataset_dir)
    problem = load_problem(dataset_dir)
    hashes = {
        "definition_sha256": defn.sha256(),
        "problem_sha256": problem_sha256(dataset_dir),
        "siblings_sha256": siblings_sha256(dataset_dir, problem),
    }
    planned, rejected = _plan(defn, getattr(problem, "feasible", None))
    if sweep is None:
        return Records(defn, hashes, planned, rejected)

    stamp_path = sweep / generate.STAMP_FILE
    stamp = _load_json(stamp_path)
    measurements_path = sweep / "datacheck" / "measurements.json"
    report = None
    if measurements_path.is_file():
        report = judge(from_json(measurements_path.read_text(encoding="utf-8")))
    source = "converge/convergence.json"
    convergence_path = sweep / "converge" / "convergence.json"
    if not convergence_path.is_file():
        # The preflight writes its own record over the pilot cases.
        source = "preflight/converge/convergence.json"
        convergence_path = sweep / "preflight" / "converge" / "convergence.json"
    convergence = _load_json(convergence_path)

    provenance: dict[str, Any] = {}
    runs: dict[str, Any] = {}
    exported: set[str] = set()
    for prov_path in sorted(sweep.glob("*/provenance.json")):
        cid = prov_path.parent.name
        provenance[cid] = json.loads(prov_path.read_text(encoding="utf-8"))
        run = _load_json(prov_path.parent / "run.json")
        if run is not None:
            runs[cid] = run
        if (prov_path.parent / f"{cid}.npz").is_file():
            exported.add(cid)
    converted: set[str] = set()
    values: dict[str, dict[str, float]] = {}
    failures: dict[str, str] = {}
    for cid in sorted(provenance):
        h5 = sweep / "canonical" / f"{cid}.h5"
        if not h5.is_file():
            continue
        converted.add(cid)
        try:
            out = problem.qoi(read_case(h5))
            values[cid] = {k: float(v) for k, v in out.items()}
        except Exception as exc:  # a QoI that raises is a finding, not a crash
            failures[cid] = f"{type(exc).__name__}: {exc}"
    return Records(
        defn,
        hashes,
        planned,
        rejected,
        sweep=True,
        stamp=stamp,
        stamp_sha256=_sha256(stamp_path) if stamp is not None else None,
        report=report,
        measurements_sha256=_sha256(measurements_path) if report else None,
        convergence=convergence,
        convergence_sha256=_sha256(convergence_path) if convergence else None,
        convergence_source=source,
        provenance=provenance,
        runs=runs,
        exported=frozenset(exported),
        converted=frozenset(converted),
        qoi_values=values,
        qoi_failures=failures,
    )


# --- formatting ------------------------------------------------------------------


def _num(value: Any) -> str:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return str(value)
    return f"{value:.6g}"


def _pct(value: Any) -> str:
    return "—" if value is None else f"{100.0 * float(value):.3g} %"


def _table(header: Sequence[str], rows: Sequence[Sequence[Any]]) -> list[str]:
    out = ["| " + " | ".join(header) + " |", "|" + "---|" * len(header)]
    for row in rows:
        cells = (str(c).replace("|", "\\|") for c in row)
        out.append("| " + " | ".join(cells) + " |")
    return out


def _absent(what: str, r: Records, stage: str) -> str:
    """The sentence a part carries when its record does not exist."""
    if not r.sweep:
        return (
            f"No sweep was read, so there is no {what}: this card was rendered "
            "from the definition alone."
        )
    return f"The sweep holds no {what}: `{stage}` has not been run on it."


# --- the parts -------------------------------------------------------------------


def part_variables(r: Records) -> str:
    d = r.defn
    out = [_source("dataset.toml", r.hashes["definition_sha256"]), ""]
    out.append(
        f"Dataset `{d.name}`, solver `{d.solver}`, deck units `{d.units}` "
        "(canonical files are SI)."
    )
    out += ["", "Sampled variables:", ""]
    out += _table(
        ["Variable", "Low", "High"],
        [[f"`{k}`", _num(lo), _num(hi)] for k, (lo, hi) in d.variables.items()],
    )
    if d.fixed:
        out += ["", "Constants every case gets:", ""]
        out += _table(
            ["Constant", "Value"], [[f"`{k}`", _num(v)] for k, v in d.fixed.items()]
        )
    if d.limits:
        out += ["", "Limits `feasible()` reads:", ""]
        out += _table(
            ["Limit", "Value"], [[f"`{k}`", _num(v)] for k, v in d.limits.items()]
        )
    rows = []
    for s in d.splits:
        if s.grid:
            kind = "grid of " + " × ".join(f"{len(v)} `{k}`" for k, v in s.grid.items())
        elif s.points:
            kind = "listed points"
        else:
            kind = f"Sobol, seed {s.seed}"
            if s.within:
                kind += f", within `{s.within}`"
            if s.exclude:
                kind += ", excluding " + ", ".join(f"`{e}`" for e in s.exclude)
        if s.variants:
            kind += "; variants " + ", ".join(f"`{v}`" for v in s.variants)
        role = [w for w, on in (("probe", s.probe), ("withheld", s.withheld)) if on]
        rows.append([f"`{s.name}`", kind, r.planned[s.name], ", ".join(role) or "—"])
    out += ["", "Splits:", ""]
    out += _table(["Split", "Design", "Cases", "Role"], rows)
    out += [
        "",
        f"Mesh levels `{'`, `'.join(d.levels.pilot)}` (refinement factors, coarse "
        f"to fine); production runs at level `{d.levels.production}`; "
        f"{d.levels.symmetry} volume weights.",
    ]
    return "\n".join(out)


def _row_counts(report: DatasetReport, quantity: str) -> Counter[str]:
    return Counter(
        str(res.verdict)
        for case in report.cases
        for res in case.results
        if res.quantity == quantity
    )


def part_stored(r: Records) -> str:
    block = r.defn.raw.get("declaration", {})
    out = [_source("dataset.toml", r.hashes["definition_sha256"]), ""]
    out.append("The dataset declares:")
    out.append("")
    for key in ("unit_system", "discretisation", "erosion", "material_family"):
        if key in block:
            value = block[key]
            said = str(value).lower() if isinstance(value, bool) else str(value)
            out.append(f"- {key.replace('_', ' ')}: `{said}`")
    fields = block.get("fields")
    if fields is None:
        out.append("- stored fields: not declared")
    else:
        out.append("- stored fields: " + ", ".join(f"`{f}`" for f in fields))
    out.append("")
    if r.report is None:
        out.append(_absent("verification record to compare it with", r, "verify"))
    else:
        counts = _row_counts(r.report, "fields_match_declaration")
        said = ", ".join(f"{v} on {n}" for v, n in sorted(counts.items())) or "no row"
        out.append(
            "Stored fields against the declared list "
            f"(`fields_match_declaration`, over {len(r.report.cases)} cases): {said}."
        )
    return "\n".join(out)


def part_qoi(r: Records) -> str:
    q = r.defn.qoi
    out = [_source("dataset.toml", r.hashes["definition_sha256"]), ""]
    ranged = bool(r.qoi_values)
    header = ["Quantity", "Unit", "Tolerance (relative)"]
    if ranged:
        header += ["Lowest", "Median", "Highest"]
    rows = []
    for name, unit, tol in zip(q.names, q.units, q.tolerance, strict=True):
        row: list[Any] = [f"`{name}`", unit, _num(tol)]
        if ranged:
            values = [v[name] for v in r.qoi_values.values() if name in v]
            if values:
                row += [
                    _num(min(values)),
                    _num(statistics.median(values)),
                    _num(max(values)),
                ]
            else:
                row += ["—", "—", "—"]
        rows.append(row)
    out += _table(header, rows)
    out.append("")
    if ranged:
        out.append(
            f"Ranges are `qoi()` over the {len(r.qoi_values)} converted cases of "
            "the sweep."
        )
    else:
        out.append(_absent("converted case to take ranges from", r, "convert"))
    for cid, why in sorted(r.qoi_failures.items()):
        out.append(f"- `qoi()` raised on {cid}: {why}")
    return "\n".join(out)


def part_survivors(r: Records) -> str:
    """The survivor log the data standard asks for (``survivor_log``, ADR-0073
    D14): every planned case accounted for, and the discarded ones named."""
    out = [
        "*From the plan (`dataset.toml`, `problem.py`) and each case's "
        "`provenance.json` and `run.json`.*",
        "",
    ]
    verified = (
        {c.case_id for c in r.report.cases} if r.report is not None else set[str]()
    )
    by_split: dict[str, list[str]] = {s.name: [] for s in r.defn.splits}
    for cid, prov in r.provenance.items():
        by_split.setdefault(str(prov.get("split")), []).append(cid)
    header = ["Split", "Planned", "Rejected by `feasible()`"]
    if r.sweep:
        header += ["Generated", "Completed", "Exported", "Converted", "Verified"]
    rows = []
    lost: list[str] = []
    for name, ids in by_split.items():
        row: list[Any] = [
            f"`{name}`",
            r.planned.get(name, "—"),
            r.rejected.get(name, 0),
        ]
        if r.sweep:
            status = {c: str(r.runs[c].get("status")) for c in ids if c in r.runs}
            row += [
                len(ids),
                sum(s == "completed" for s in status.values()),
                sum(c in r.exported for c in ids),
                sum(c in r.converted for c in ids),
                sum(c in verified for c in ids),
            ]
            lost += [f"{c}: {s}" for c, s in sorted(status.items()) if s != "completed"]
            lost += [f"{c}: not run" for c in sorted(ids) if c not in r.runs]
            lost += [
                f"{c}: completed, no canonical file"
                for c in sorted(ids)
                if status.get(c) == "completed" and c not in r.converted
            ]
        rows.append(row)
    out += _table(header, rows)
    out.append("")
    if not r.sweep:
        out.append(_absent("run record", r, "run"))
    elif lost:
        out.append("Cases that did not survive to a canonical file:")
        out.append("")
        out += [f"- {line}" for line in lost]
    else:
        out.append("Every generated case completed and has a canonical file.")
    out += [
        "",
        "A rejected draw is a Sobol point the definition's `feasible()` refused; "
        "the next point takes its place, so a split keeps its size. Of the "
        "data standard's other required items, `noise_floor` and "
        "`constitutive_sensitivity` are produced by no stage: where they exist "
        "they are the author's to state.",
    ]
    return "\n".join(out)


_VERDICT_ORDER = (
    Verdict.PASS,
    Verdict.FAIL,
    Verdict.REVIEW,
    Verdict.NOT_ASSESSABLE,
    Verdict.NOT_APPLICABLE,
)


def part_verification(r: Records) -> str:
    if r.report is None:
        return _absent(
            "verification record (`datacheck/measurements.json`)", r, "verify"
        )
    report = r.report
    out = [_source("datacheck/measurements.json", r.measurements_sha256), ""]
    covered = {c.case_id for c in report.cases}
    completed = {c for c, run in r.runs.items() if run.get("status") == "completed"}
    out.append(
        f"The record covers {len(covered)} cases, judged by StructBench "
        f"{report.measurements.structbench_version}; a pass is a necessary sign "
        "of a healthy run, not evidence that the simulation matches reality."
    )
    uncovered = sorted(completed - covered)
    if uncovered:
        splits = sorted({str(r.provenance[c].get("split")) for c in uncovered})
        out.append(
            f"**It is partial**: {len(uncovered)} completed cases of the sweep "
            f"are not in it (splits: {', '.join(splits)}). `verify` writes one "
            "record per sweep and a run over some splits replaces the others'."
        )
    per_row: dict[str, Counter[str]] = {}
    for case in report.cases:
        for res in case.results:
            per_row.setdefault(res.quantity, Counter())[str(res.verdict)] += 1
    kinds: Counter[str] = Counter()
    for counts in per_row.values():
        worst = next(
            str(v) for v in _VERDICT_ORDER[1:] + (Verdict.PASS,) if counts[str(v)]
        )
        kinds[worst] += 1
    out += ["", "Rows by their worst verdict over the cases:", ""]
    out += _table(
        ["Verdict", "Rows"],
        [[str(v), kinds[str(v)]] for v in _VERDICT_ORDER if kinds[str(v)]],
    )
    accepted = set(r.defn.pilot.accepted_gaps)
    failing = {q: c for q, c in per_row.items() if c[str(Verdict.FAIL)]}
    review = {q: c for q, c in per_row.items() if c[str(Verdict.REVIEW)]}
    if failing or review:
        out += ["", "Rows that fail or need review:", ""]
        rows = []
        for q in sorted({*failing, *review}):
            c = per_row[q]
            note = "an accepted gap of the definition" if q in accepted else ""
            rows.append([f"`{q}`", c[str(Verdict.FAIL)], c[str(Verdict.REVIEW)], note])
        out += _table(["Row", "Cases failing", "Cases to review", "Note"], rows)
    else:
        out += ["", "No row fails and none needs review."]
    unused = sorted(accepted - set(failing))
    if accepted:
        out += [
            "",
            "The definition accepts as known gaps (`[pilot].accepted_gaps`): "
            + ", ".join(f"`{g}`" for g in sorted(accepted))
            + (
                "; of these, no case fails " + ", ".join(f"`{g}`" for g in unused) + "."
                if unused
                else "."
            ),
        ]
    judged = {c.quantity for c in report.criteria}
    spreads = []
    for q in sorted(per_row):
        if q in judged:
            continue
        values = [
            m.value
            for case in report.measurements.cases
            for m in case.measurements
            if m.quantity == q and m.value is not None
        ]
        if values:
            spreads.append(
                [
                    f"`{q}`",
                    len(values),
                    _num(min(values)),
                    _num(statistics.median(values)),
                    _num(max(values)),
                ]
            )
    if spreads:
        out += ["", "Measured, with no criterion to judge by:", ""]
        out += _table(["Row", "Cases", "Lowest", "Median", "Highest"], spreads)
    return "\n".join(out)


def part_convergence(r: Records) -> str:
    """The convergence run the data standard asks for (``convergence_run``)."""
    c = r.convergence
    if c is None:
        return _absent(
            "convergence record (`converge/convergence.json`)", r, "converge"
        )
    out = [_source(r.convergence_source, r.convergence_sha256), ""]
    levels = c.get("level_order") or sorted(c.get("levels", {}))
    counts = ", ".join(f"level {lv}: {c['levels'].get(lv, 0)}" for lv in levels)
    out.append(
        f"{len(c.get('cases', []))} cases compared across mesh levels ({counts}); "
        f"production level `{c.get('production_level')}`."
    )
    if c.get("anchor"):
        out.append(
            f"Probe split `{c['anchor']}` anchors the comparison: its run at the "
            "production level stands for production."
        )
    rows = []
    for name in r.defn.qoi.names:
        s = (c.get("summary", {}).get("qoi") or {}).get(name)
        if not s:
            rows.append([f"`{name}`", "—", "—", "—", "—", "not extrapolated"])
            continue
        e = s.get("error_at_production_level") or {}
        statuses = ", ".join(f"{k} {v}" for k, v in sorted(s["statuses"].items()))
        orders = [
            case["extrapolation"][name]["order"]
            for case in c.get("cases", [])
            if (case.get("extrapolation") or {}).get(name)
            and case["extrapolation"][name].get("order") is not None
        ]
        order = _num(statistics.median(orders)) if orders else "—"
        rows.append(
            [
                f"`{name}`",
                e.get("n", 0),
                _pct(e.get("median")),
                _pct(e.get("max")),
                order,
                statuses or "—",
            ]
        )
    out += ["", "Quantities of interest against their extrapolated values:", ""]
    out += _table(
        [
            "Quantity",
            "Extrapolations",
            "Median error at production",
            "Highest",
            "Observed order (median)",
            "Statuses",
        ],
        rows,
    )
    fields = c.get("summary", {}).get("fields") or {}
    rows = [
        [f"`{f}`", lv, s["n"], _pct(s["median"]), _pct(s["max"])]
        for f in sorted(fields)
        for lv in levels
        if (s := fields[f].get(lv))
    ]
    if rows:
        out += ["", "Stored fields against the finest level (pooled relative L2):", ""]
        out += _table(["Field", "Level", "Cases", "Median", "Highest"], rows)
    notes = len(c.get("notes", [])) + sum(len(k["notes"]) for k in c.get("cases", []))
    if notes:
        out += ["", f"The record carries {notes} notes; `convergence.md` lists them."]
    return "\n".join(out)


def part_resolution(r: Records) -> str:
    s = r.stamp
    if s is None:
        return _absent("preflight stamp (`preflight/stamp.json`)", r, "preflight")
    out = [_source("preflight/stamp.json", r.stamp_sha256), ""]
    other = [k for k, v in r.hashes.items() if s.get(k) != v]
    if other:
        out.append(
            "**The stamp is for another definition** ("
            + ", ".join(f"`{k}` differs" for k in other)
            + "): the numbers below describe the definition it was made for."
        )
        out.append("")
    verdict = "passed" if s.get("passed") else "did not pass"
    out.append(
        f"The preflight of {str(s.get('created_utc', ''))[:10]} {verdict} "
        f"({len(sum(s.get('cases', {}).values(), []))} cases)."
    )
    steps = s.get("steps", {})

    def detail(name: str) -> dict[str, Any]:
        return (steps.get(name) or {}).get("detail") or {}

    def verdict_of(name: str) -> str:
        return str((steps.get(name) or {}).get("verdict", "not run"))

    d = r.defn
    out += [
        "",
        f"**Space** (`{verdict_of('space')}`): production at mesh level "
        f"`{d.levels.production}` of `{'`, `'.join(d.levels.pilot)}`.",
    ]
    space = detail("space")
    rows = []
    for name in d.qoi.names:
        errors = [
            c[name]["error_at_production"]
            for c in (space.get("cases") or {}).values()
            if name in c and c[name].get("error_at_production") is not None
        ]
        tol = (space.get("tolerance") or {}).get(name)
        worst = _pct(max(errors)) if errors else "not extrapolated"
        rows.append([f"`{name}`", worst, _pct(tol)])
    if rows:
        out += [""] + _table(
            ["Quantity", "Highest error at production", "Tolerance"], rows
        )

    inc = detail("increment")
    out += [
        "",
        f"**Solver increment** (`{verdict_of('increment')}`): "
        f"`{d.pilot.increment_key}` = {_num(inc.get('production_value'))} in "
        "production.",
    ]
    changes: dict[str, dict[str, float]] = {}
    for per_value in (inc.get("pilots") or {}).values():
        for value, per_qoi in per_value.items():
            for name, change in per_qoi.items():
                if change is not None:
                    slot = changes.setdefault(value, {})
                    slot[name] = max(slot.get(name, 0.0), abs(float(change)))
    for value in sorted(changes):
        said = ", ".join(f"`{n}` {_pct(c)}" for n, c in sorted(changes[value].items()))
        out.append(
            f"- at `{d.pilot.increment_key}` = {value}, the highest change over the "
            f"pilots: {said}"
        )

    frame = detail("frame")
    out += [
        "",
        f"**Stored frame interval** (`{verdict_of('frame')}`): "
        f"`{d.pilot.frame_key}` = {_num(d.fixed.get(d.pilot.frame_key))}, "
        f"`{d.pilot.frame_count_key}` = {_num(d.fixed.get(d.pilot.frame_count_key))}.",
    ]
    judged = frame.get("judged") or []
    frame_errors = {
        k: v for k, v in (frame.get("interpolation") or {}).items() if k in judged
    }
    if frame_errors:
        frame_worst = max(frame_errors, key=lambda k: frame_errors[k] or 0.0)
        out.append(
            f"- an export at {_num(frame.get('factor'))} of the interval is "
            "predicted from the stored frames to "
            f"{_pct(frame_errors[frame_worst])} at worst "
            f"(`{frame_worst}`, of {len(judged)} judged fields; tolerance "
            f"{_pct(d.pilot.frame_tolerance)})"
        )
    for key, row in sorted((frame.get("reported") or {}).items()):
        out.append(
            f"- `{key}` reported, not judged ({_pct(row.get('error'))}): "
            f"{row.get('reason', '')}"
        )

    dur = detail("duration")
    out += [
        "",
        f"**Duration** (`{verdict_of('duration')}`): "
        f"{_num(dur.get('frames'))} stored frames over a horizon of "
        f"{_num(dur.get('horizon'))} s.",
    ]
    pilots = dur.get("pilots") or {}
    settle = [
        p["settling_frame"]
        for p in pilots.values()
        if p.get("settling_frame") is not None
    ]
    if settle:
        shares = [
            p["share_after_settling"]
            for p in pilots.values()
            if p.get("share_after_settling") is not None
        ]
        out.append(
            f"- the pilots settle between frames {min(settle)} and {max(settle)} "
            f"(limit {_num(dur.get('settling_limit_frame'))}); the share of the "
            f"horizon after settling is at least {_pct(min(shares))}"
        )
    separation = [
        p["separation_frame"]
        for p in pilots.values()
        if p.get("separation_frame") is not None
    ]
    if separation:
        out.append(
            f"- `{dur.get('contact_force_global')}` falls below a thousandth of "
            f"its peak between frames {min(separation)} and {max(separation)} "
            "over the pilots"
        )
    for key, reason in sorted((s.get("accepted_reviews") or {}).items()):
        out.append(f"- review `{key}` accepted by the definition: {reason}")
    for key, row in sorted((s.get("accepted_increment") or {}).items()):
        out.append(
            f"- increment change `{key}` accepted by the definition: "
            f"{row.get('reason', '')}"
        )
    return "\n".join(out)


def part_provenance(r: Records) -> str:
    out = [
        "*From the definition and each case's `provenance.json` and `run.json`.*",
        "",
    ]
    out += _table(
        ["File", "sha256 (LF endings)"],
        [
            ["`dataset.toml`", f"`{r.hashes['definition_sha256']}`"],
            ["`problem.py`", f"`{r.hashes['problem_sha256']}`"],
            ["sibling modules of `problem.py`", f"`{r.hashes['siblings_sha256']}`"],
        ],
    )
    out.append("")
    if not r.provenance:
        out.append(_absent("generated case", r, "generate"))
    else:
        other = sum(
            any(p.get(k) != v for k, v in r.hashes.items())
            for p in r.provenance.values()
        )
        out.append(
            f"{len(r.provenance)} cases generated"
            + (
                f"; **{other} of them under another definition** than the one "
                "hashed above."
                if other
                else ", all under the definition hashed above."
            )
        )
        builds = Counter(
            (
                str((p.get("repository") or {}).get("version")),
                str((p.get("repository") or {}).get("commit") or "no commit")[:12],
            )
            for p in r.provenance.values()
        )
        for (version, commit), n in sorted(builds.items()):
            out.append(f"- StructBench {version} ({commit}): {n} cases")
        commits = Counter(
            str((p.get("dataset_repository") or {}).get("commit") or "no commit")[:12]
            for p in r.provenance.values()
        )
        for commit, n in sorted(commits.items()):
            out.append(f"- the definition's commit {commit}: {n} cases")
        gates = Counter(
            "probe split, not gated"
            if p.get("preflight") is None
            else "generated without a preflight"
            if p["preflight"].get("skipped")
            else "against a passing preflight stamp"
            for p in r.provenance.values()
        )
        for gate, n in sorted(gates.items()):
            out.append(f"- {gate}: {n} cases")
        solvers = Counter(
            str(run.get("abaqus_version") or "not recorded") for run in r.runs.values()
        )
        for version, n in sorted(solvers.items()):
            out.append(f"- solver release {version} ({r.defn.solver}): {n} runs")
        stand_in = sum(_stand_in(run) for run in r.runs.values())
        if stand_in:
            out.append(
                f"- **{stand_in} runs were launched with a script in the solver's "
                "place (`--solver-args`): they are not simulations, and nothing "
                "measured on them is reference data.**"
            )
    sweep = f"<runs>/{r.defn.name}"
    out += [
        "",
        "To reproduce, with the definition's directory as `<dir>`:",
        "",
        "    structbench-datagen check     <dir>",
        "    structbench-datagen preflight --dataset <dir> --work-root <runs>",
        "    structbench-datagen generate  --dataset <dir> --work-root <runs>",
        f"    structbench-datagen run       --sweep {sweep}",
        f"    structbench-datagen export    --sweep {sweep}",
        f"    structbench-datagen convert   --sweep {sweep}",
        f"    structbench-datagen verify    --sweep {sweep} --dataset <dir>",
        f"    structbench-datagen converge  --sweep {sweep} --dataset <dir>",
        f"    structbench-datagen card      --sweep {sweep} --dataset <dir>",
    ]
    return "\n".join(out)


def _stand_in(run: Mapping[str, Any]) -> bool:
    """Whether the run's recorded command carries arguments between the
    executable and the job: a stand-in for the solver (`run --solver-args`)."""
    command = [str(a) for a in run.get("command") or []]
    return len(command) > 1 and not command[1].startswith("job=")


RENDERERS: dict[str, Callable[[Records], str]] = {
    "variables": part_variables,
    "stored": part_stored,
    "qoi": part_qoi,
    "survivors": part_survivors,
    "verification": part_verification,
    "convergence": part_convergence,
    "resolution": part_resolution,
    "provenance": part_provenance,
}


def render(dataset_dir: Path, sweep: Path | None, text: str) -> str:
    """The card ``text`` with every generated part rendered from the records."""
    _spans(text.replace("\r\n", "\n"))  # refuse before any record is read
    records = load_records(dataset_dir, sweep)
    return render_card(text, {p: RENDERERS[p](records) for p in PARTS})


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="structbench-datagen card", description=(__doc__ or "").splitlines()[0]
    )
    parser.add_argument("--dataset", type=Path, required=True)
    parser.add_argument(
        "--sweep",
        type=Path,
        help="the sweep whose records fill the card; without it the card is "
        "rendered from the definition alone and says so",
    )
    parser.add_argument("--out", type=Path, help=f"default: <dataset>/{CARD_FILE}")
    parser.add_argument(
        "--check",
        action="store_true",
        help="write nothing; exit 1 when the card differs from its render",
    )
    args = parser.parse_args(argv)
    dataset_dir = args.dataset.resolve()
    card = dataset_dir / CARD_FILE
    if not card.is_file():
        print(f"{dataset_dir.name}: no {CARD_FILE}", file=sys.stderr)
        return 2
    if args.sweep is not None and not args.sweep.is_dir():
        print(f"{args.sweep} is not a directory", file=sys.stderr)
        return 2
    current = card.read_bytes().decode("utf-8")
    try:
        rendered = render(dataset_dir, args.sweep, current)
    except (CardError, DefinitionError) as exc:
        print(f"{dataset_dir.name}: {exc}", file=sys.stderr)
        return 2
    target = args.out or card
    if args.check:
        on_disk = target.read_bytes().decode("utf-8") if target.is_file() else ""
        if on_disk.replace("\r\n", "\n") != rendered:
            print(f"{target.name} differs from its render; run card without --check")
            return 1
        print(f"{target.name} is its render")
        return 0
    target.write_bytes(rendered.encode("utf-8"))
    print(f"rendered {len(PARTS)} parts -> {target.name}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
